-- 5. checks: every voucher line points at a ledger and a Books project that exist, and the salary sheet at its staff
do $$ declare bad text; begin
  select string_agg(distinct v.path || ' → ' || (c->>'p'), ', ') into bad
  from public.books_docs v, jsonb_array_elements(v.data->'lines') l, jsonb_array_elements(coalesce(l->'cc', '[]')) c
  where v.coll = 'vouchers' and not exists (select 1 from public.books_docs p where p.path = 'projects/' || (c->>'p'));
  if bad is not null then raise exception 'Vouchers point at projects that are not in Books: %. Nothing was changed.', bad; end if;
  select string_agg(distinct v.path, ', ') into bad
  from public.books_docs v, jsonb_array_elements(v.data->'lines') l
  where v.coll = 'vouchers' and not exists (select 1 from public.books_docs x where x.path = 'ledgers/' || (l->>'l'));
  if bad is not null then raise exception 'Vouchers point at missing ledgers: %. Nothing was changed.', bad; end if;
  select string_agg(r->>'name', ', ') into bad from public.books_docs s, jsonb_array_elements(s.data->'rows') r
  where s.path = 'payroll/2026-10' and not exists (select 1 from public.books_docs x where x.path = 'staff/' || (r->>'staffId'));
  if bad is not null then raise exception 'The salary sheet names staff not in Books: %. Nothing was changed.', bad; end if;
end $$;

commit;
